import{_ as t,o as e,c as s,ag as i}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"快速安装","description":"在 Ubuntu 24 上按向导安装 InduFrame v1.0，了解更新和卸载的基本操作。","frontmatter":{"title":"快速安装","description":"在 Ubuntu 24 上按向导安装 InduFrame v1.0，了解更新和卸载的基本操作。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/installation/quick-install.md","filePath":"zh/安装运维/快速安装.md"}'),d={name:"zh/installation/quick-install.md"};function o(n,a,l,h,r,c){return e(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="快速安装" tabindex="-1">快速安装 <a class="header-anchor" href="#快速安装" aria-label="Permalink to &quot;快速安装&quot;">​</a></h1><p>本页适用于 <strong>InduFrame v1.0</strong>。<strong>优先推荐 Ubuntu 24，这是目前已测试的系统；其他系统尚未测试。</strong> 不确定系统或安装包是否合适时，先请交付人员确认。</p><h2 id="安装前" tabindex="-1">安装前 <a class="header-anchor" href="#安装前" aria-label="Permalink to &quot;安装前&quot;">​</a></h2><p>将适用的完整安装包上传到服务器并完整解压，不要只取出其中的脚本。服务器账号需要有系统管理权限，也就是能够使用 <code>sudo</code>。</p><p>系统盘和另行使用的数据盘，都须同时保留至少 <strong>30 GiB 且 20% 的可用空间</strong>，另为业务数据增长预留容量。准备好组织成员能访问的服务器地址，以及自己设置的平台管理员密码。</p><p>不会连接服务器、上传文件或进入安装包文件夹时，可先请服务器维护人员协助。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>在服务器终端进入解压后的安装包文件夹，确认其中有 <code>install.sh</code>，再执行：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span></span></code></pre></div><ol><li>如果询问系统密码，输入当前服务器账号的密码，不是平台登录密码。</li><li>按向导填写安装位置、访问地址和端口。默认位置为 <code>/opt</code>，实际程序目录为 <code>/opt/induframe</code>；公共端口默认 <code>443</code>，管理端口默认 <code>18100</code>。采用默认值时直接回车。</li><li>没有专门准备证书时，在证书方式处回车使用默认的 <code>self-signed</code>；有现成证书文件时，再由维护人员选择 <code>provided</code>。</li><li>设置平台超级管理员用户名和密码。默认用户名为 <code>admin</code>；建议密码使用 8–72 个英文字母、数字或半角符号，并输入两次。</li><li>保持终端连接，等到 <strong>“InduFrame 中心安装完成。”</strong>、命令正常结束，并列出公共入口、管理入口和日志路径。</li></ol><p>保存这两个完整地址。先打开<strong>管理入口</strong>，以安装时设置的平台账号登录，在“组织管理”为默认组织重置管理员密码；再从<strong>公共入口</strong>用组织管理员账号登录。</p><p>详细步骤见<a href="/induframe-docs/zh/installation/install.html">安装中心</a>和<a href="/induframe-docs/zh/installation/first-setup.html">完成首次设置</a>。浏览器提示证书不受信任时，先请维护人员核对地址与证书，再处理信任。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><p>先向交付人员确认新完整包适用于当前平台，安排暂停使用和备份。将新包解压到另一个文件夹，进入后仍执行：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span></span></code></pre></div><p>出现 <code>1) 更新</code>、<code>2) 取消</code> 时，输入 <code>1</code> 才更新；输入 <code>2</code> 或直接回车取消，确认前已有平台保持原状。</p><p>更新沿用原安装位置、访问设置和账号。等待最终完成提示后，用原账号检查两个入口及实际业务数据。不要自行尝试未经确认的跨版本更新。</p><p>只有交付人员明确提供<strong>小型补丁包</strong>时，才按补丁说明运行其中的 <code>./update.sh</code>；完整安装包统一使用 <code>./install.sh</code>。</p><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><p>先通知使用者，决定是否保留数据。在完整安装包文件夹执行：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./uninstall.sh</span></span></code></pre></div><p>原包不在时，可用已安装的卸载脚本。默认位置是：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/induframe/uninstall.sh</span></span></code></pre></div><table tabindex="0"><thead><tr><th>终端问到什么</th><th>应怎样回答</th></tr></thead><tbody><tr><td>是否确定卸载</td><td>输入 <code>y</code> 继续；输入 <code>n</code> 或回车取消</td></tr><tr><td>是否同时删除平台数据与运行环境</td><td>保留数据时输入 <code>n</code> 或回车；确定删除时才输入 <code>y</code></td></tr><tr><td>输入 PURGE 确认</td><td>只在确定永久删除时输入大写 <code>PURGE</code></td></tr></tbody></table><p><strong>两次回车的含义不同：第一次是取消卸载，第二次是卸载服务并保留数据。</strong> 需要重装时，先看<a href="/induframe-docs/zh/installation/reinstall.html">保留数据后重新安装</a>的条件。</p><p>删除无法撤回。如果另行询问是否删除服务器原有运行环境，默认保留；不清楚其中是否有别的服务时，不要同意删除。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><p>保留终端完整提示和日志路径，先看<a href="/induframe-docs/zh/installation/troubleshooting.html">安装常见问题</a>。没有安装完成提示、或卸载显示未完成时，不要靠反复重装或手工删除目录试错。</p><p>若终端报告仍有采集数据或系统规则需要处理，交给维护人员核对；卸载结束不代表这些留存事项也已处理完。</p>',29)])])}const g=t(d,[["render",o]]);export{u as __pageData,g as default};
